def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def to_pos(v, default=(0, 0)):
        try:
            if isinstance(v, (list, tuple)) and len(v) >= 2:
                return int(v[0]), int(v[1])
        except Exception:
            pass
        return default

    def get_pos(key, default=(0, 0)):
        return to_pos(observation.get(key, default), default)

    def move_toward(src, tgt):
        sx, sy = src
        tx, ty = tgt
        return [clamp_step(tx - sx), clamp_step(ty - sy)]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def pick_best(points, src, prefer_far=False):
        best = None
        best_score = None
        for p in points or []:
            pos = to_pos(p, None)
            if pos is None:
                continue
            score = manhattan(src, pos)
            if prefer_far:
                score = -score
            if best is None or score < best_score:
                best = pos
                best_score = score
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = get_pos("self_position", (0, 0))
    ox, oy = get_pos("opponent_position", (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return move_toward(self_pos, opp_pos)
        gw = observation.get("grid_width", 10)
        gh = observation.get("grid_height", 10)
        try:
            gw = int(gw)
        except Exception:
            gw = 10
        try:
            gh = int(gh)
        except Exception:
            gh = 10
        corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        target = pick_best(corners, opp_pos, prefer_far=True)
        if target is None:
            return [0, 0]
        return move_toward(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells")
        if not targets:
            targets = observation.get("opponent_territory")
        if not targets:
            targets = observation.get("territory_targets")
        target = pick_best(targets, self_pos, prefer_far=False)
        if target is not None:
            return move_toward(self_pos, target)
        return move_toward(self_pos, opp_pos)

    resources = observation.get("resources")
    target = pick_best(resources, self_pos, prefer_far=False)
    if target is not None:
        return move_toward(self_pos, target)
    return move_toward(self_pos, opp_pos)

